import { prisma } from "@/lib/db";
import { getServerSession } from "next-auth/next";
import { authOptions } from "@/lib/auth";
import { NextResponse } from "next/server";

// GET - Fetch all users with pagination and filtering
export async function GET(request: Request) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user?.email) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    // Check if user is admin (using session role)
    const userRole = (session.user as any).role?.toLowerCase();
    console.log("🔍 User role:", userRole);

    if (userRole !== "admin") {
      return NextResponse.json({ error: "Forbidden - Admin access required" }, { status: 403 });
    }

    const { searchParams } = new URL(request.url);
    const page = parseInt(searchParams.get("page") || "1");
    const limit = parseInt(searchParams.get("limit") || "10");
    const search = searchParams.get("search") || "";
    const role = searchParams.get("role") || "";
    const status = searchParams.get("status") || "";

    const skip = (page - 1) * limit;

    const whereClause: any = {};

    if (search) {
      whereClause.OR = [
        { email: { contains: search, mode: "insensitive" } },
        { username: { contains: search, mode: "insensitive" } },
        { student: { name: { contains: search, mode: "insensitive" } } },
        { company: { name: { contains: search, mode: "insensitive" } } }
      ];
    }

    if (role && role !== "all") {
      whereClause.accountRole = {
        name: { equals: role.toLowerCase(), mode: "insensitive" }
      };
    }

    if (status && status !== "all") {
      whereClause.is_active = status === "active";
    }

    // Exclude pending companies from Manage Users
    whereClause.NOT = {
      company: {
        registration_status: "pending"
      }
    };

    const [accounts, totalCount] = await Promise.all([
      prisma.account.findMany({
        where: whereClause,
        select: {
          id: true,
          email: true,
          username: true,
          created_at: true,
          updated_at: true,
          is_active: true,
          accountRole: {
            select: {
              id: true,
              name: true
            }
          },
          student: {
            select: {
              id: true,
              student_id: true,
              name: true,
              faculty: true,
              year: true,
              phone: true
            }
          },
          company: {
            select: {
              id: true,
              name: true,
              address: true,
              phone: true,
              description: true,
              website: true,
              registration_status: true
            }
          }
        },
        orderBy: {
          created_at: "desc"
        },
        skip,
        take: limit
      }),
      prisma.account.count({ where: whereClause })
    ]);

    const processedUsers = accounts.map(account => {
      const user: any = {
        id: account.id,
        name: account.username || account.email.split('@')[0],
        email: account.email,
        role: account.accountRole?.name?.toLowerCase() || "unknown",
        isActive: account.is_active,
        createdAt: account.created_at,
        updatedAt: account.updated_at,
        profile: {}
      };

      // Add role-specific profile information
      if (account.student) {
        user.profile = {
          phone: account.student.phone,
          department: account.student.faculty,
          studentId: account.student.student_id
        };
      } else if (account.company) {
        user.profile = {
          phone: account.company.phone,
          location: account.company.address,
          companyName: account.company.name,
          companySize: account.company.description // Using description as company size placeholder
        };
      }

      return user;
    });

    return NextResponse.json({
      users: processedUsers,
      pagination: {
        page,
        limit,
        totalCount,
        totalPages: Math.ceil(totalCount / limit)
      }
    }, { status: 200 });

  } catch (error) {
    console.error("API error:", error);
    return NextResponse.json({ error: "Failed to fetch users" }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/db';
import { getApiSession } from '@/lib/api-auth';
import { StudentStatus, VerificationStatus } from '@prisma/client';

/**
 * GET /api/admin/verifications
 * Get all students pending verification (alumni)
 */
export async function GET(req: NextRequest) {
  try {
    // Get session and verify admin access
    const session = await getApiSession(req);

    if (!session?.user?.id) {
      return NextResponse.json(
        { error: 'Unauthorized' },
        { status: 401 }
      );
    }

    // Verify user is admin
    const adminAccount = await prisma.account.findUnique({
      where: { id: parseInt(session.user.id) },
      include: { accountRole: true },
    });

    if (!adminAccount || adminAccount.accountRole?.name !== 'admin') {
      return NextResponse.json(
        { error: 'Forbidden - Admin access required' },
        { status: 403 }
      );
    }

    // Get query parameters
    const { searchParams } = new URL(req.url);
    const status = searchParams.get('status') || 'PENDING';

    // Build where clause
    const whereClause: {
      student_status: StudentStatus;
      verification_status?: VerificationStatus;
    } = {
      student_status: StudentStatus.ALUMNI,
    };

    if (status && ['PENDING', 'APPROVED', 'REJECTED'].includes(status)) {
      whereClause.verification_status = status as VerificationStatus;
    }

    // Fetch students
    const students = await prisma.student.findMany({
      where: whereClause,
      include: {
        account: {
          select: {
            email: true,
            created_at: true,
          },
        },
        verifiedByAdmin: {
          select: {
            username: true,
          },
        },
      },
      orderBy: {
        created_at: 'desc',
      },
    });

    // Format response
    const formattedStudents = students.map((student) => ({
      id: student.id,
      student_id: student.student_id,
      name: student.name,
      email: student.account?.email || '',
      faculty: student.faculty,
      year: student.year,
      verification_status: student.verification_status,
      email_verified: student.email_verified,
      transcript: student.transcript,
      verified_by: student.verifiedByAdmin?.username,
      verified_at: student.verified_at,
      created_at: student.created_at,
      account_created_at: student.account?.created_at,
    }));

    return NextResponse.json(
      {
        students: formattedStudents,
        total: formattedStudents.length,
      },
      { status: 200 }
    );
  } catch (error) {
    console.error('Error fetching verifications:', error);
    return NextResponse.json(
      { error: 'Internal server error' },
      { status: 500 }
    );
  }
}

import { prisma } from "@/lib/db";
import { NextResponse } from "next/server";
import { getServerSession } from "next-auth/next";
import { authOptions } from "@/lib/auth";

export async function GET() {
  const session = await getServerSession(authOptions);
  if (!session) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
  }

  try {
    const company = await prisma.company.findUnique({
      where: { account_id: Number(session.user.id) },
    });

    if (!company) {
      return NextResponse.json({ error: "Company not found" }, { status: 404 });
    }

    const companyId = company.id;

  const jobs = await prisma.jobPost.findMany({
    where: { company_id: companyId },
    include: {
        category: { select: { name: true } },
        tags: true,
        documents: true,
        applications: true,
        company: { include: { account: true } },
        jobType: true,
        jobArrangement: true,
    },
    orderBy: { created_at: "desc" },
  });

    const mappedJobs = jobs.map((job) => {
      let status = "active";
      if (!job.is_Published) status = "draft";
      else if (job.deadline && new Date(job.deadline) < new Date()) status = "expire";

      return {
        id: job.id,
        title: job.jobName,
        companyName: job.company.name,
        companyLogo: job.company.account?.logoUrl || "/default-logo.png",
        companyBg: job.company.account?.backgroundUrl || "/default-bg.png",
        location: job.location,
        posted: job.created_at.toISOString(),
        applied: job.applications.length,
        salary: { min: job.min_salary, max: job.max_salary },
        type: job.jobType.name,
        arrangement: job.jobArrangement.name,
        category: job.category?.name ?? "",
        skills: job.tags.map((t) => t.name),
        documents: Array.isArray(job.documents) ? job.documents.map((d: any) => d.name) : [],
        deadline: job.deadline.toISOString(),
        status,
        description: {
            overview: job.aboutRole ?? "",
            responsibility: job.responsibilities ?? "-",
            requirement: job.requirements.join("\n"),
            qualification: job.qualifications.join("\n"),
        },
      };
    });

    return NextResponse.json(mappedJobs, { status: 200 });
  } catch (error) {
    console.error("API error:", error);
    return NextResponse.json({ error: "Failed to fetch jobs" }, { status: 500 });
  }
}

