      name: company.name,
      address: [company.address], // Convert to array for compatibility
      description: company.description,
      department: [], // Companies don't have departments in schema, empty array for compatibility
      year: new Date().getFullYear(), // Not used for companies but required by interface
      phone: company.phone,
      registration_status: company.registration_status as "PENDING" | "APPROVED" | "REJECTED",
      verification_notes: company.verification_notes,
      documents: {
        evidence: company.account.documents.map(doc => ({
          id: doc.id,
          name: doc.file_name,
          url: doc.file_path,
          uploadedAt: doc.created_at.toISOString(),
          type: doc.documentType.name
        }))
      }
    };

    return NextResponse.json(response);
  } catch (error) {
    console.error("Error fetching company profile:", error);
    return NextResponse.json({ error: "Failed to fetch company profile" }, { status: 500 });
  }
}

export async function PATCH(request: NextRequest) {
  try {
    const session = await getServerSession(authOptions);
    if (!session?.user?.email) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const formData = await request.formData();

    // Get the account
    const account = await prisma.account.findUnique({
      where: { email: session.user.email },
      include: { company: true }
    });

    if (!account?.company) {
      return NextResponse.json({ error: "Company not found" }, { status: 404 });
    }

    // Extract form data
    const name = formData.get("name") as string | null;
    const address = formData.get("address") as string | null;
    const phone = formData.get("phone") as string | null;
    const description = formData.get("description") as string | null;
    const website = formData.get("website") as string | null;
    const logoFile = formData.get("logo") as File | null;
    const backgroundFile = formData.get("background") as File | null;

    // Validate required fields
    if (name && name.trim().length < 3) {
      return NextResponse.json({ error: "Company name must be at least 3 characters" }, { status: 400 });
    }
    if (phone && !/^\d{10,}$/.test(phone)) {
      return NextResponse.json({ error: "Phone number must be at least 10 digits" }, { status: 400 });
    }
    if (description && description.trim().length < 10) {
      return NextResponse.json({ error: "Description must be at least 10 characters" }, { status: 400 });
    }

    // Handle image uploads
    let logoUrl = account.logoUrl;
    let backgroundUrl = account.backgroundUrl;

    if (logoFile && logoFile.size > 0) {
      try {
        const { uploadImage } = await import("@/lib/uploadImage");
        logoUrl = await uploadImage(logoFile, String(account.id), "logo");
      } catch (error) {
        console.error("Error uploading logo:", error);
        return NextResponse.json({ error: "Failed to upload logo image" }, { status: 500 });
      }
    }

    if (backgroundFile && backgroundFile.size > 0) {
      try {
        const { uploadImage } = await import("@/lib/uploadImage");
        backgroundUrl = await uploadImage(backgroundFile, String(account.id), "background");
      } catch (error) {
        console.error("Error uploading background:", error);
        return NextResponse.json({ error: "Failed to upload background image" }, { status: 500 });
      }
    }

    // Update account images if changed
    if (logoUrl !== account.logoUrl || backgroundUrl !== account.backgroundUrl) {
      await prisma.account.update({
        where: { id: account.id },
        data: {
          logoUrl,
          backgroundUrl
        }
      });
    }

    // Update company information
    const updatedCompany = await prisma.company.update({
      where: { id: account.company.id },
      data: {
        ...(name && { name: name.trim() }),
        ...(address && { address: address.trim() }),
        ...(phone && { phone: phone.trim() }),
        ...(description && { description: description.trim() }),
        ...(website !== null && { website: website.trim() || null }),
        updated_at: new Date()
      }
    });

    return NextResponse.json({
      message: "Profile updated successfully",
      company: updatedCompany,
      logoUrl,
      backgroundUrl
    }, { status: 200 });

  } catch (error) {
    console.error("Error updating company profile:", error);
    return NextResponse.json({ error: "Failed to update company profile" }, { status: 500 });
  }
}

import { getApiSession } from "@/lib/api-auth";
import { prisma } from "@/lib/db";
import { NextRequest, NextResponse } from "next/server";

/**
 * GET /api/company/recent-applications
 *
 * Returns the most recent applications for the logged-in company
 *
 * Query Parameters:
 * - limit: number (default: 5) - How many applications to return
 * - offset: number (default: 0) - For pagination
 *
 * Example: /api/company/recent-applications?limit=5
 */
export async function GET(request: NextRequest) {
  try {
    const session = await getApiSession(request);

    if (!session?.user?.id) {
      return NextResponse.json(
        { error: "Unauthorized. Please login." },
        { status: 401 }
      );
    }

    const company = await prisma.company.findUnique({
      where: { account_id: parseInt(session.user.id) },
      select: { id: true }
    });

    if (!company) {
      return NextResponse.json(
        { error: "No company found for this account." },
        { status: 403 }
      );
    }

    const companyId = company.id;
    const limitParam = request.nextUrl.searchParams.get("limit");
    const offsetParam = request.nextUrl.searchParams.get("offset");
    const limit = limitParam ? parseInt(limitParam) : 5;
    const offset = offsetParam ? parseInt(offsetParam) : 0;

    const totalApplications = await prisma.application.count({
      where: {
        jobPost: { company_id: companyId }
      }
    });

    const applications = await prisma.application.findMany({
      where: {
        jobPost: { company_id: companyId }
      },
      include: {
        student: {
          include: {
            account: {
              select: {
                id: true,
                email: true,
                logoUrl: true // This is the profile picture
              }
            }
          }
        },
        jobPost: {
          select: {
            id: true,
            jobName: true
          }
        },
        applicationStatus: {
          select: {
            name: true
          }
        }
      },
      orderBy: {
        applied_at: "desc"
      },
      take: limit,
      skip: offset
    });

    // eslint-disable-next-line @typescript-eslint/no-explicit-any
    const formattedApplications = applications.map((app: any) => ({
      id: app.id,
      applicant: {
        id: app.student.id,
        name: app.student.name,
        email: app.student.account.email,
        profile_url: app.student.account.logoUrl || null
      },
      job: {
        id: app.jobPost.id,
        title: app.jobPost.jobName
      },
      status: app.applicationStatus.name.toLowerCase(),
      applied_at: app.applied_at.toISOString()
    }));

    return NextResponse.json({
      success: true,
      data: {
        applications: formattedApplications,
        total: totalApplications,
        limit: limit,
        offset: offset
      }
    });

  } catch (error) {
    console.error("Error fetching recent applications:", error);
    return NextResponse.json(
      { error: "Internal Server Error" },
      { status: 500 }
    );
  }
}

import { getApiSession } from "@/lib/api-auth";
import { prisma } from "@/lib/db";
import { NextRequest, NextResponse } from "next/server";

/**
 * GET /api/company/top-jobs
 *
 * Returns the top performing job posts by application count
 *
 * Query Parameters:
 * - limit: number (default: 5) - How many jobs to return
 * - sortBy: "applications" | "views" (default: "applications")
 *
 * Example: /api/company/top-jobs?limit=5
 */
export async function GET(request: NextRequest) {
  try {
    const session = await getApiSession(request);

    if (!session?.user?.id) {
      return NextResponse.json(
        { error: "Unauthorized. Please login." },
        { status: 401 }
      );
    }

    const company = await prisma.company.findUnique({
      where: { account_id: parseInt(session.user.id) },
      select: { id: true }
    });

    if (!company) {
      return NextResponse.json(
        { error: "No company found for this account." },
        { status: 403 }
      );
    }

    const companyId = company.id;
    const limitParam = request.nextUrl.searchParams.get("limit");
    const limit = limitParam ? parseInt(limitParam) : 5;
    const now = new Date();

    const jobs = await prisma.jobPost.findMany({
      where: {
        company_id: companyId
      },
      include: {
        applications: {
          select: {
            id: true
          }
        }
      },
      take: limit * 2
    });

    const jobsWithStats = jobs.map((job: { id: number; jobName: string; is_Published: boolean; deadline: Date; applications: { id: number }[] }) => {
      let status: "active" | "draft" | "closed";

      if (!job.is_Published) {
        status = "draft";
      } else if (job.deadline < now) {
        status = "closed";
      } else {
        status = "active";
      }

      return {
        id: job.id,
        title: job.jobName,
        applications: job.applications.length,
        views: 0,
        status: status
      };
    });

    jobsWithStats.sort((a: { applications: number }, b: { applications: number }) => b.applications - a.applications);
    const topJobs = jobsWithStats.slice(0, limit);

    return NextResponse.json({
      success: true,
      data: {
        jobs: topJobs
      }
    });

  } catch (error) {
    console.error("Error fetching top jobs:", error);
    return NextResponse.json(
      { error: "Internal Server Error" },
      { status: 500 }
    );
  }
}

import { prisma } from "@/lib/db";
import { NextResponse, NextRequest } from "next/server";

export async function GET(request: Request, context: { params: Promise<{ id: string }> }) {
  try {
    const { id } = await context.params;
    const job = await prisma.jobPost.findFirst({
      where: { id: Number(id) },
      include: {
        category: true,
        tags: true,
        applications: true,
        company: { include: { account: true } },
        jobType: true,
        jobArrangement: true,
        documents: true,
      },
    });

    if (!job) {
      return NextResponse.json({ error: "Job not found" }, { status: 404 });
    }

    // Derive status from is_Published and deadline
    let status = "active";
    if (!job.is_Published) {
      status = "draft";
    } else if (job.deadline && new Date(job.deadline) < new Date()) {
      status = "expire";
    }

    const mappedJob = {
      id: job.id,
      companyLogo: job.company.account?.logoUrl ?? "",
      companyBg: job.company.account?.backgroundUrl ?? "",
      title: job.jobName,
      companyName: job.company.name,
      category: job.category?.name ?? "",
      location: job.location,
      posted: job.created_at.toISOString(),
      applied: job.applications.length,
      salary: {
        min: Number(job.min_salary),
        max: Number(job.max_salary),
      },
      type: job.jobType.name,
      description: {
        overview: job.aboutRole ?? "",
        responsibility: job.responsibilities ?? "-",
        requirement: job.requirements.join("\n"),
        qualification: job.qualifications.join("\n"),
      },
      skills: job.tags.map((tag: { name: string }) => tag.name),
      arrangement: job.jobArrangement.name,
      deadline: job.deadline ? job.deadline.toISOString() : null,
      status,
      documents: job.documents.map((doc: { name: string }) => doc.name.toLowerCase()),
    };
    return NextResponse.json(mappedJob);
  } catch (error) {
    console.error("API error:", error);
    return NextResponse.json({ error: "Failed to fetch job" }, { status: 500 });
  }
}


export async function DELETE(
  request: NextRequest,
  context: { params: Promise<{ id: string }> }
) {
  try {
    const { getApiSession } = await import("@/lib/api-auth");
    const session = await getApiSession(request);

    if (!session?.user?.id) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { id } = await context.params;
    const jobId = Number(id);

    const existingJob = await prisma.jobPost.findFirst({
      where: { id: jobId },
      include: { company: true },
    });

    if (!existingJob) {
      return NextResponse.json({ error: "Job not found" }, { status: 404 });
    }

    // Verify the company owns this job
    if (existingJob.company.account_id !== parseInt(session.user.id)) {
      return NextResponse.json({ error: "Forbidden: You don't own this job" }, { status: 403 });
    }

    // Check if company is still verified
    if (existingJob.company.registration_status !== "APPROVED") {
      return NextResponse.json(
        { error: "Your company must be verified to manage jobs. Please check your verification status in your profile page." },
        { status: 403 }
      );
    }

    await prisma.jobPost.delete({
      where: { id: jobId },
    });

    return NextResponse.json({ message: "Job deleted successfully" }, { status: 200 });
  } catch (error) {
    console.error("DELETE /api/jobs/[id] error:", error);
    return NextResponse.json({ error: "Failed to delete job" }, { status: 500 });
  }
}


export async function PATCH(
  request: NextRequest,
  context: { params: Promise<{ id: string }> }
) {
  try {
    const { getApiSession } = await import("@/lib/api-auth");
    const session = await getApiSession(request);

    if (!session?.user?.id) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const { id } = await context.params;
    const jobId = Number(id);

    const existingJob = await prisma.jobPost.findFirst({
      where: { id: jobId },
      include: { tags: true, category: true, company: true },
    });

    if (!existingJob) {
      return NextResponse.json({ error: "Job not found" }, { status: 404 });
    }

    // Verify the company owns this job
    if (existingJob.company.account_id !== parseInt(session.user.id)) {
      return NextResponse.json({ error: "Forbidden: You don't own this job" }, { status: 403 });
    }

    // Check if company is still verified
    if (existingJob.company.registration_status !== "APPROVED") {
      return NextResponse.json(
        { error: "Your company must be verified to manage jobs. Please check your verification status in your profile page." },
        { status: 403 }
      );
    }

    const body = await request.json();

    const arrangement = body.arrangement
      ? await prisma.jobArrangement.findFirst({ where: { name: body.arrangement } })
      : null;


    const type = body.type
      ? await prisma.jobType.findFirst({ where: { name: body.type } })
      : null;

    if ((body.arrangement && !arrangement) || (body.type && !type)) {
      return NextResponse.json({ error: "Invalid arrangement or type" }, { status: 400 });
    }

    // Handle tags: find existing or create new ones
    const tagIds: { id: number }[] = [];
    if (body.tags?.length) {
      for (const tagName of body.tags) {
        // Try to find existing tag
        let tag = await prisma.jobTag.findFirst({
          where: { name: tagName },
        });

        // If tag doesn't exist, create it
        if (!tag) {
          tag = await prisma.jobTag.create({
            data: { name: tagName },
          });
        }

        tagIds.push({ id: tag.id });
      }
    }

    const documentIds = body.requiredDocuments?.length
      ? await prisma.documentType.findMany({
          where: { name: { in: body.requiredDocuments } },
          select: { id: true },
        })
      : [];

    let categoryId = existingJob.job_category_id;
    if (body.category) {
      const category = await prisma.jobCategory.findFirst({ where: { name: body.category } });
      if (!category) {
        return NextResponse.json({ error: "Category not found" }, { status: 400 });
      }
      categoryId = category.id;
    }

    const updatedJob = await prisma.jobPost.update({
      where: { id: jobId },
      data: {
        location: body.location ?? existingJob.location,
        job_arrangement_id: arrangement?.id ?? existingJob.job_arrangement_id,
        job_type_id: type?.id ?? existingJob.job_type_id,
        min_salary: body.min_salary ?? existingJob.min_salary,
        max_salary: body.max_salary ?? existingJob.max_salary,
        aboutRole: body.aboutRole ?? existingJob.aboutRole,
        responsibilities: body.responsibilities ?? existingJob.responsibilities,
        requirements: body.requirements ?? existingJob.requirements,
        qualifications: body.qualifications ?? existingJob.qualifications,
        tags: tagIds.length ? { set: tagIds.map(tag => ({ id: tag.id })) } : undefined,
        job_category_id: categoryId,
        deadline: body.deadline ? new Date(body.deadline) : existingJob.deadline,
        documents: documentIds.length ? { set: documentIds.map(doc => ({ id: doc.id })) } : undefined,
      },
    });

    return NextResponse.json({
      message: "Job updated successfully",
      job: updatedJob,
    });
  } catch (error) {
    console.error("PATCH /api/jobs/[id] error:", error);
    return NextResponse.json({ error: "Failed to update job" }, { status: 500 });
  }
}

import { prisma } from "@/lib/db";
import { NextResponse } from "next/server";

export async function GET(req: Request) {
  try {
    const { searchParams } = new URL(req.url);
    const userId = searchParams.get("userId");

    let studentId: number | null = null;

    // If userId is provided, find the corresponding student
    if (userId) {
      const student = await prisma.student.findUnique({
        where: { account_id: Number(userId) },
      });
      studentId = student?.id ?? null;
    }

    const today = new Date();

    // Removed unknown 'documents' include to satisfy Prisma include typing.
    // Cast result to any[] so TypeScript won't complain about optional relation properties.
    const jobs = (await prisma.jobPost.findMany({
      where: {
        is_Published: true,
        deadline: {
          gte: today,
        },
      },
      include: {
        category: true,
        tags: true,
        applications: true,
        company: {
          include: {
            account: true,
          },
        },
        jobType: true,
        jobArrangement: true,
        savedBy: studentId
          ? {
              where: {
                student_id: studentId,
              },
            }
          : false,
      },
    })) as any[];


    type JobWithRelations = {
      id: number;
      is_Published: boolean;
      deadline: Date;
      savedBy: unknown;
      jobName: string;
      company: { name: string; account: { logoUrl: string | null; backgroundUrl: string | null } | null };
      category: { id: number; name: string } | null;
      location: string;
      created_at: Date;
      applications: unknown[];
      min_salary: number | bigint;
      max_salary: number | bigint;
      jobType: { name: string };
      aboutRole: string | null;
      responsibilities: string | null,
      requirements: string[];
      qualifications: string[];
      tags: { name: string }[];
      documents?: { name: string }[]; // optional now, guard access at runtime
      jobArrangement: { name: string };
    };

  const mappedData = jobs.map((job) => {
      // Derive status from is_Published and deadline
      let status = "active";
      if (!job.is_Published) {
        status = "draft";
      } else if (job.deadline && new Date(job.deadline) < new Date()) {
        status = "expire";
      }

      // Check if the job is saved by the current user
      const isSaved = Array.isArray(job.savedBy) && job.savedBy.length > 0;

      return {
        id: job.id,
        companyLogo: job.company.account?.logoUrl ?? "",
        companyBg: job.company.account?.backgroundUrl ?? "",
        title: job.jobName,
        companyName: job.company.name,
        category: job.category ? job.category.name : "",
        location: job.location,
        posted: job.created_at.toISOString(),
        applied: job.applications.length,
        salary: {
          min: Number(job.min_salary),
          max: Number(job.max_salary),
        },
        type: job.jobType.name,
        description: {
          overview: job.aboutRole ?? "",
          responsibility: job.responsibilities ?? "-",
          requirement: job.requirements.join("\n"),
          qualification: job.qualifications.join("\n"),
        },
        skills: job.tags.map((tag: { name: string }) => tag.name),
        requiredDocuments: Array.isArray(job.documents) ? job.documents.map((d: { name: string }) => d.name) : [],
        arrangement: job.jobArrangement.name,
        deadline: job.deadline ? job.deadline.toISOString() : null,
        status,
        isSaved,
      };
    });
    // console.log("Mapped jobs to JSON:", mappedData);
    return NextResponse.json(mappedData);
  } catch (error) {
    console.error("API error:", error);
    return NextResponse.json({ error: "Failed to fetch jobs" }, { status: 500 });
  }
}

import { NextResponse } from "next/server";
import { prisma } from "@/lib/db";

export async function GET(
  request: Request,
  context: { params: Promise<{ id: string }> }
) {
  try {
    const { id } = await context.params;
    const accountId = Number(id);

    if (isNaN(accountId)) {
      return NextResponse.json({ error: "Invalid account ID" }, { status: 400 });
    }

    const student = await prisma.student.findUnique({
      where: { account_id: accountId },
      select: { id: true },
    });

    if (!student) {
      return NextResponse.json({ error: "Student not found" }, { status: 404 });
    }

    const statusData = await prisma.application.groupBy({
      by: ["status"],
      where: { student_id: student.id },
      _count: { id: true },
    });

    const result = await Promise.all(
      statusData.map(async (item) => {
        const status = await prisma.applicationStatus.findUnique({
          where: { id: item.status },
        });
        return {
          name: status?.name || "Unknown",
          value: item._count.id,
        };
      })
    );

    return NextResponse.json(result);
  } catch (error) {
    console.error("Error fetching status data:", error);
    return NextResponse.json({ error: "Failed to fetch data" }, { status: 500 });
  }
}

