import { toast } from "sonner";


type StatusType = "pending" | "reviewed" | "interview" | "offered" | "rejected";

const statusColor: Record<string, string> = {
	pending: "bg-yellow-100 text-yellow-800",
	reviewed: "bg-blue-100 text-blue-800",
	interview: "bg-indigo-100 text-indigo-800",
	offered: "bg-green-100 text-green-800",
	rejected: "bg-red-100 text-red-800",
};

export default function RecentApplicationsTable({ applications, loading, isCompanyVerified = true }: RecentApplicationsTableProps & { isCompanyVerified?: boolean }) {
  const items = Array.isArray(applications) ? applications : [];

  const statusTypes: StatusType[] = ["pending", "reviewed", "interview", "offered", "rejected"];
  const [statusMap, setStatusMap] = useState<Record<string, StatusType>>(
      () =>
        Object.fromEntries(
          items.map((a) => [a.id, a.status as StatusType])
        )
  );

  const handleStatus = async (application_id: string, newStatus: StatusType) => {
    // Optimistically update UI
    const previousStatus = statusMap[application_id];
    setStatusMap((prev) => ({ ...prev, [application_id]: newStatus }));

    try {
      const response = await fetch(`/api/company/applications/${application_id}`, {
        method: "PATCH",
        headers: {
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          status: newStatus,
        }),
      });

      if (!response.ok) {
        const error = await response.json();
        console.error("Failed to update application status:", error);
        // Revert to previous status on error
        setStatusMap((prev) => ({ ...prev, [application_id]: previousStatus }));
        toast.error("Failed to update status", {
          description: error.error || "Unknown error occurred"
        });
      } else {
        const result = await response.json();
        console.log("Application status updated successfully:", result);
        toast.success("Status updated", {
          description: `Application status changed to ${newStatus}`
        });
      }
    } catch (error) {
      console.error("Error updating application status:", error);
      // Revert to previous status on error
      setStatusMap((prev) => ({ ...prev, [application_id]: previousStatus }));
      toast.error("Error updating status", {
        description: "An error occurred. Please try again."
      });
    }
  };

	return (
    <div className="flex flex-col rounded-md shadow-lg w-full gap-4 p-4 overflow-y-auto h-[500px]">
      <p className="text-lg font-semibold text-gray-700">Recent Applications</p>
      {items.length === 0 ? (
      <div className="flex flex-col items-center justify-center py-10 text-gray-500">
        <p className="text-center text-sm">No applicants yet</p>
      </div>
    ) : (
      <div className="flex flex-col gap-2">
        <div className="flex flex-row items-center justify-between px-3 py-2 text-sm font-medium text-gray-600 shadow-md rounded-md bg-[#FFEFE5]">
          <div className="flex items-center gap-4 w-1/4 min-w-0">
            <span>Name</span>
          </div>
          <div className="w-1/4 hidden sm:block">Email</div>
          <div className="w-1/4 hidden md:block pl-6">Position</div>
          <div className="w-32">Status</div>
          <div className="w-24">Profile</div>
        </div>
        {items.map((student) => {
          const currentStatus = statusMap[student.id] || (student.status as StatusType);
          return (
            <div
              key={student.id}
              className="flex flex-row items-center justify-between px-2 py-3 hover:bg-gray-50 border-b"
            >
              <div className="flex items-center gap-4 w-1/4 min-w-0">
                {isValidImageUrl(student.applicant.profile_url) ? (
                  <Image
                    src={student.applicant.profile_url}
                    alt={`${student.applicant.name} profile`}
                    width={40}
                    height={40}
                    className="w-[40px] h-[40px] object-cover rounded-full shadow-sm"
                  />
                ) : (
                  <div className="w-[40px] h-[40px] flex items-center justify-center rounded-full shadow-sm bg-gray-100 text-sm font-semibold text-gray-700">
                    {`${(student.applicant.name?.[0] || "").toUpperCase()}`}
                  </div>
                )}
                <div className="truncate">
                  <div className="text-sm font-medium text-gray-900 truncate">{student.applicant.name}</div>
                </div>
              </div>

              <div className="w-1/4 hidden sm:block truncate text-sm text-gray-600">{student.applicant.email}</div>

              <div className="w-1/4 hidden md:block text-sm text-gray-600 pl-6">{student.job.title}</div>

              <div className="w-32">
                <div className="w-32">
                  <Select
                    value={currentStatus}
                    onValueChange={(val) =>
                      handleStatus(student.id, val as StatusType)
                    }
                    disabled={!isCompanyVerified}
                  >
                    <SelectTrigger
                      data-testid={`application-status-trigger-${student.id}`}
                      className={`rounded-full text-sm transition-all duration-200 border-none p-2 h-5 w-[110px] ${statusColor[currentStatus]} ${!isCompanyVerified ? 'opacity-60 cursor-not-allowed' : ''}`}
                    >
                      <SelectValue />
                    </SelectTrigger>
                    <SelectContent>
                      <SelectGroup>
                        <SelectLabel>Status</SelectLabel>
                        {statusTypes.map((status) => (
                          <SelectItem key={status} value={status}>
                            {status}
                          </SelectItem>
                        ))}
                      </SelectGroup>
                    </SelectContent>
                  </Select>
                </div>
              </div>

              <div className="w-24 text-right">
                <StudentInfoModal applicant_id={student.id} size="sm" />
              </div>
            </div>
          );
        })}
      </div>

    )}
    </div>
  );
}

"use client";
import React, { useEffect, useState } from "react";
import Image from "next/image";
import {
  Select,
  SelectContent,
  SelectGroup,
  SelectItem,
  SelectLabel,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import StudentInfoModal from "@/components/StudentInfoModal";
import { toast } from "sonner";

interface Applicant {
  application_id: number;
  applicant_id: number;
  profile_url: string;
  name: string;
  email: string;
  status: string;
  applied_at: Date;
}

interface Status {
  id: number;
  name: string;
}

interface ApplicantListProps {
  applicants: Applicant[];
  isCompanyVerified?: boolean;
  loading?: boolean;
}

type StatusType = "pending" | "reviewed" | "interview" | "offered" | "rejected";

const statusColors: Record<StatusType, string> = {
  pending: "bg-yellow-100 text-yellow-800",
  reviewed: "bg-blue-100 text-blue-800",
  interview: "bg-purple-100 text-purple-800",
  offered: "bg-green-100 text-green-800",
  rejected: "bg-red-100 text-red-800",
};

const ApplicationList = ({ applicants, isCompanyVerified = true, loading = false }: ApplicantListProps) => {
  const [statusList, setStatusList] = useState<Status[]>([]);
  const [statusMap, setStatusMap] = useState<Record<number, { id: number; type: StatusType }>>({});
  const [avatarError, setAvatarError] = useState<Record<string, boolean>>({});

  useEffect(() => {
    fetch("/api/application-status")
      .then((res) => res.json())
      .then((data) => {
        setStatusList(data.statuses);

        const initialMap: Record<number, { id: number; type: StatusType }> = {};
        applicants.forEach((a) => {
          const s = data.statuses.find((st: Status) => String(st.id) === a.status);
          initialMap[Number(a.application_id)] = {
            id: Number(a.status),
            type: (s?.name.toLowerCase() as StatusType) || "pending",
          };
        });
        setStatusMap(initialMap);
      })
      .catch(console.error);
  }, [applicants]);

  const handleStatusChange = async (application_id: number, newStatusId: number) => {
    console.log("handleStatusChange called", { application_id, newStatusId });
    const s = statusList.find((st) => st.id === newStatusId);
    if (!s) return;
    const previous = statusMap[application_id];

    setStatusMap((prev) => ({
      ...prev,
      [application_id]: { id: newStatusId, type: s.name.toLowerCase() as StatusType },
    }));

    try {
      const response = await fetch(`/api/applications/${application_id}/status`, {
        method: "PATCH",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ status_id: newStatusId }),
      });

      let result: { error?: string } | null = null;
      try {
        result = await response.json();
      } catch {
        // ignore parse errors
      }

      if (!response.ok) {
        console.error("Failed to update status:", result || response.statusText);
        toast.error("Failed to update status", {
          description: result?.error || "Please try again.",
        });
        // revert optimistic update
        setStatusMap((prev) => ({ ...prev, [application_id]: previous }));
        return;
      }

      console.log("Application status updated successfully:", result);
      toast.success("Status updated", {
        description: `Application status changed to ${s.name}`,
      });
    } catch (error) {
      console.error("Failed to update status:", error);
      toast.error("Failed to update application status");
      setStatusMap((prev) => ({ ...prev, [application_id]: previous }));
    }
  };

  return (
    <div className="flex flex-col rounded-md bg-white border border-gray-100 w-full gap-4 p-4 h-[350px]">
      <p className="text-lg font-semibold text-gray-700">Student Applications</p>
      <div className="overflow-y-auto">
        {loading ? (
          <div className="flex flex-col gap-4">
            {[1, 2, 3].map((i) => (
              <div
                key={i}
                className="flex flex-col md:flex-row md:justify-between items-start md:items-center gap-3 md:gap-0 shadow-sm rounded-lg p-3 border border-gray-100 bg-white animate-pulse"
              >
                <div className="flex flex-row gap-4 items-center min-w-0">
                  <div className="w-14 h-14 flex-shrink-0 rounded-full bg-gray-200"></div>
                  <div className="flex flex-col gap-2">
                    <div className="h-4 w-32 bg-gray-200 rounded"></div>
                    <div className="h-3 w-48 bg-gray-200 rounded"></div>
                  </div>
                </div>
                <div className="flex flex-row items-center gap-3 w-full md:w-auto mt-2 md:mt-0 justify-end md:justify-start">
                  <div className="w-32 h-8 bg-gray-200 rounded-full"></div>
                  <div className="w-20 h-8 bg-gray-200 rounded"></div>
                </div>
              </div>
            ))}
          </div>
        ) : applicants.length === 0 ? (
        <div className="flex flex-col items-center justify-center py-10 text-gray-500">
          <p className="text-center text-sm">No applicants yet</p>
        </div>
      ) : (
        <div className="flex flex-col gap-4">
          {applicants.map((student) => {
            const currentStatus = statusMap[Number(student.application_id)] || {
              id: Number(student.status),
              type: statusList.find(s => s.id === Number(student.status))?.name.toLowerCase() as StatusType || 'pending'
              };

            return (
              <div
                key={student.application_id}
                className="group flex flex-col shadow-sm rounded-lg p-3 border border-gray-100 transition transition-transform duration-300 hover:-translate-y-1 hover:shadow-md bg-white hover:bg-[#F3FEFA]"
              >
                <div className="flex flex-col md:flex-row md:justify-between items-start md:items-center gap-3 md:gap-0">
                  <div className="flex flex-row gap-4 items-center min-w-0">
                    <div className="w-14 h-14 flex-shrink-0 rounded-full overflow-hidden bg-white shadow-sm">
                      {student.profile_url && !avatarError[student.applicant_id] ? (
                        <Image
                          src={student.profile_url ?? "/assets/images/companyLogo.png"}
                          alt="studentProfile"
                          width={56}
                          height={56}
                          onError={() =>
                            setAvatarError((prev) => ({ ...prev, [student.applicant_id]: true }))
                          }
                          className="object-cover w-full h-full transition-transform duration-200 ease-in-out group-hover:scale-105"
                        />
                      ) : (
                        <div className="w-full h-full flex items-center justify-center text-sm font-medium text-gray-700 bg-gray-100">
                          {student.name ? student.name.charAt(0).toUpperCase() : "C"}
                        </div>
                      )}
                    </div>
                    <div className="flex flex-col">
                      <div className="flex flex-col sm:flex-row gap-2 items-start sm:items-center">
                        <p className="font-medium">{student.name}</p>
                      </div>
                      <p className="text-sm text-gray-500 truncate max-w-full sm:max-w-[200px] md:max-w-none">{student.email}</p>
                    </div>
                  </div>
                  <div className="flex flex-row items-center gap-3 w-full md:w-auto mt-2 md:mt-0 justify-end md:justify-start">
                    <div className="w-32 flex-shrink-0">
                      <Select
                        value={String(currentStatus.id)}
                        onValueChange={(val) =>
                          handleStatusChange(Number(student.application_id), Number(val))
                        }
                        disabled={!isCompanyVerified}
                      >
                        <SelectTrigger
                          data-testid={`application-status-trigger-${student.application_id}`}
                          className={`rounded-full w-full text-sm transition-all duration-200 border-none p-3 ${statusColors[currentStatus.type as StatusType]} ${!isCompanyVerified ? 'opacity-60 cursor-not-allowed' : ''}`}
                        >
                          <SelectValue placeholder="Select status">
                              {statusList.find((st) => st.id === currentStatus.id)?.name || "Pending"}
                          </SelectValue>
                        </SelectTrigger>
                        <SelectContent>
                          <SelectGroup>
                            <SelectLabel>Status</SelectLabel>
                            {statusList.map((status) => (
                              <SelectItem
                                  key={status.id}
                                  value={status.id.toString()}
                                >
                                  {status.name.charAt(0).toUpperCase() + status.name.slice(1)}
                                </SelectItem>
                            ))}
                          </SelectGroup>
                        </SelectContent>
                      </Select>
                    </div>

                    <div className="flex-shrink-0">
                      <StudentInfoModal applicant_id={student.application_id.toString()} />
                    </div>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      )}
      </div>
    </div>
  );
};

export default ApplicationList;

