            <div className="flex flex-row gap-6">
                <div className="flex flex-col gap-2 w-full">
                    <p className="text-sm font-semibold text-gray-800">Type</p>
                    <Select onValueChange={(value) => handleSelect("type", value)}>
                        <SelectTrigger data-testid="select-job-type" className="w-full">
                            <SelectValue placeholder={formData.type || "Select Type"} />
                          </SelectTrigger>
                        <SelectContent>
                            {types.map((type) => (
                            <SelectItem key={type} value={type}>
                            {type}
                        </SelectItem>
                       ))}
                        </SelectContent>
                    </Select>
                </div>

              <div className="flex flex-col gap-2 w-full">
                <p className="text-sm font-semibold text-gray-800">Arrangement</p>
                <Select onValueChange={(value) => handleSelect("arrangement", value)}>
                  <SelectTrigger data-testid="select-arrangement" className="w-full">
                    <SelectValue placeholder={formData.arrangement || "Select Arrangement"} />
                  </SelectTrigger>
                  <SelectContent>
                    {arrangements.map((arr) => (
                      <SelectItem key={arr} value={arr}>{arr}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </div>

            <div className="flex flex-row gap-6">
              <div className="flex flex-col gap-2 w-full">
                <p className="text-sm font-semibold text-gray-800">Min Salary (THB)</p>
                <div className="relative">
                  <span className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-500 text-sm">฿</span>
                  <Input
                    data-testid="min-salary-input"
                    type="number"
                    min={0}
                    name="minSalary"
                    value={formData.salary.min || ""}
                    onChange={(e) => setFormData({ ...formData,
                      salary: {
                        ...formData.salary,
                        min: e.target.value === "" ? 0 : Math.max(0, Number(e.target.value))
                    }})}
                    required={true}
                    placeholder="30000"
                    className="pl-8"
                  />
                </div>
              </div>
              <div className="flex flex-col gap-2 w-full">
                <p className="text-sm font-semibold text-gray-800">Max Salary (THB)</p>
                <div className="relative">
                  <span className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-500 text-sm">฿</span>
                  <Input
                    data-testid="max-salary-input"
                    type="number"
                    min={0}
                    name="maxSalary"
                    value={formData.salary.max || ""}
                    onChange={(e) => setFormData({ ...formData,
                      salary: {
                        ...formData.salary,
                        max: e.target.value === "" ? 0 : Math.max(0, Number(e.target.value))
                    }})}
                    required={true}
                    placeholder="60000"
                    className="pl-8"
                  />
                </div>
              </div>
            </div>

            <div className="flex flex-col gap-2 w-full">
                <p className="text-sm font-semibold text-gray-800">Deadline</p>
                <Input
                  data-testid="deadline-input"
                  type="date"
                  name="deadline"
                  value={formData.deadline}
                  onChange={(e) => setFormData({ ...formData, deadline: e.target.value })}
                  required={true}
                />
            </div>
            <div>
              <h3 className="text-sm font-semibold text-gray-800 mb-2">Required Documents</h3>
              <div className="flex flex-col gap-2">
                {[
                  { key: 'resume', label: 'Resume' },
                  { key: 'cv', label: 'CV' },
                  { key: 'portfolio', label: 'Portfolio' },
                  { key: 'transcript', label: 'Transcript' },
                ].map((doc) => {
                  const checked = formData.documents?.includes(doc.key) ?? false;
                  return (
                    <label key={doc.key} className="inline-flex items-center gap-3">
                      <input
                        data-testid={`reqdoc-${doc.key}`}
                        type="checkbox"
                        className="w-4 h-4"
                        checked={checked}
                        onChange={(e) => {
                          setFormData((prev) => {
                            const list = new Set(prev.documents || []);
                            if (e.target.checked) list.add(doc.key);
                            else list.delete(doc.key);
                            return { ...prev, documents: Array.from(list) };
                          });
                        }}
                      />
                      <span className="text-sm text-gray-700">{doc.label}</span>
                    </label>
                  );
                })}
              </div>
            </div>
        </div>
    );
}
export default JobPostDetailSection;

"use client";

import { Company } from "@/types/user";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Textarea } from "@/components/ui/textarea";
import { IoBusinessOutline, IoCallOutline, IoGlobeOutline, IoLocationOutline, IoMailOutline, IoShieldCheckmarkOutline, IoCamera, IoSave, IoClose } from "react-icons/io5";
import { useState, useRef } from "react";
import { toast } from "sonner";
import Image from "next/image";
import { isValidImageUrl } from "@/lib/validateImageUrl";
import { useSession } from "next-auth/react";

interface ProfileTabProps {
  company: Company;
  onProfileUpdate?: () => void;
}

export default function ProfileTab({ company, onProfileUpdate }: ProfileTabProps) {
  const [isEditing, setIsEditing] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const { data: session, update: updateSession } = useSession();

  // Form state
  const [formData, setFormData] = useState({
    name: company.name,
    address: company.address[0] || "",
    phone: company.phone,
    description: company.description,
    website: company.department[0] || "", // Using department[0] as website placeholder
  });

  // Image upload refs and previews
  const logoInputRef = useRef<HTMLInputElement>(null);
  const backgroundInputRef = useRef<HTMLInputElement>(null);
  const [logoPreview, setLogoPreview] = useState<string | null>(null);
  const [backgroundPreview, setBackgroundPreview] = useState<string | null>(null);
  const [logoFile, setLogoFile] = useState<File | null>(null);
  const [backgroundFile, setBackgroundFile] = useState<File | null>(null);

  const getStatusColor = (status: string) => {
    switch (status) {
      case "APPROVED":
        return "bg-green-100 text-green-800 border-green-300";
      case "PENDING":
        return "bg-yellow-100 text-yellow-800 border-yellow-300";
      case "REJECTED":
        return "bg-red-100 text-red-800 border-red-300";
      default:
        return "bg-gray-100 text-gray-800 border-gray-300";
    }
  };

  const getStatusText = (status: string) => {
    switch (status) {
      case "APPROVED":
        return "Verified";
      case "PENDING":
        return "Verification Pending";
      case "REJECTED":
        return "Verification Rejected";
      default:
        return status;
    }
  };

  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>, type: "logo" | "background") => {
    const file = e.target.files?.[0];
    if (file) {
      // Validate file type
      if (!file.type.startsWith("image/")) {
        toast.error("Please select an image file");
        return;
      }

      // Validate file size (max 5MB)
      if (file.size > 5 * 1024 * 1024) {
        toast.error("Image size must be less than 5MB");
        return;
      }

      const reader = new FileReader();
      reader.onloadend = () => {
        if (type === "logo") {
          setLogoPreview(reader.result as string);
          setLogoFile(file);
        } else {
          setBackgroundPreview(reader.result as string);
          setBackgroundFile(file);
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const handleSave = async () => {
    // Validation
    if (formData.name.trim().length < 3) {
      toast.error("Company name must be at least 3 characters");
      return;
    }
    if (formData.phone && !/^\d{10,}$/.test(formData.phone)) {
      toast.error("Phone number must be at least 10 digits");
      return;
    }
    if (formData.description.trim().length < 10) {
      toast.error("Description must be at least 10 characters");
      return;
    }

    setIsSaving(true);
    try {
      const form = new FormData();
      form.append("name", formData.name.trim());
      form.append("address", formData.address.trim());
      form.append("phone", formData.phone.trim());
      form.append("description", formData.description.trim());
      form.append("website", formData.website.trim());

      if (logoFile) {
        form.append("logo", logoFile);
      }
      if (backgroundFile) {
        form.append("background", backgroundFile);
      }

      const response = await fetch("/api/company/profile", {
        method: "PATCH",
        body: form,
      });

      if (response.ok) {
        const data = await response.json();
        toast.success("Profile updated successfully");

        // Update session if logo or background was changed
        if (logoFile || backgroundFile) {
          await updateSession({
            user: {
              ...session?.user,
              logoUrl: data.logoUrl,
              backgroundUrl: data.backgroundUrl,
            },
          });
        }

        setIsEditing(false);
        setLogoPreview(null);
        setBackgroundPreview(null);
        setLogoFile(null);
        setBackgroundFile(null);
        onProfileUpdate?.();
      } else {
        const error = await response.json();
        toast.error(error.error || "Failed to update profile");
      }
    } catch (error) {
      console.error("Error updating profile:", error);
      toast.error("An error occurred while updating profile");
    } finally {
      setIsSaving(false);
    }
  };

  const handleCancel = () => {
    setFormData({
      name: company.name,
      address: company.address[0] || "",
      phone: company.phone,
      description: company.description,
      website: company.department[0] || "",
    });
    setLogoPreview(null);
    setBackgroundPreview(null);
    setLogoFile(null);
    setBackgroundFile(null);
    setIsEditing(false);
  };

  return (
    <Card>
      <CardHeader>
        <div className="flex items-center justify-between">
          <div>
            <CardTitle>Company Information</CardTitle>
            <CardDescription>
              {isEditing ? "Edit your company profile details" : "View your company profile details"}
            </CardDescription>
          </div>
          <div className="flex gap-2">
            {!isEditing ? (
              <Button onClick={() => setIsEditing(true)}>
                Edit Profile
              </Button>
            ) : (
              <>
                <Button variant="outline" onClick={handleCancel} disabled={isSaving}>
                  <IoClose className="w-4 h-4 mr-2" />
                  Cancel
                </Button>
                <Button onClick={handleSave} disabled={isSaving}>
                  <IoSave className="w-4 h-4 mr-2" />
                  {isSaving ? "Saving..." : "Save Changes"}
                </Button>
              </>
            )}
          </div>
        </div>
      </CardHeader>
      <CardContent className="space-y-6">
        {/* Profile Images Section */}
        {isEditing && (
          <div className="space-y-4 pb-6 border-b">
            <h3 className="text-sm font-medium">Profile Images</h3>

            {/* Logo Upload */}
            <div>
              <Label className="text-sm font-medium mb-2 block">Company Logo</Label>
              <div className="flex items-center gap-4">
                <div className="relative w-24 h-24 rounded-full overflow-hidden border-2 border-gray-200 bg-gray-100">
                  {logoPreview || isValidImageUrl(company.profile_url) ? (
                    <Image
                      src={logoPreview || company.profile_url!}
                      alt="Company Logo"
                      fill
                      className="object-cover"
                      onError={(e) => {
                        e.currentTarget.style.display = 'none';
                      }}
                    />
                  ) : (
                    <div className="w-full h-full flex items-center justify-center">
                      <IoBusinessOutline className="w-12 h-12 text-gray-400" />
                    </div>
                  )}
                </div>
                <div>
                  <input
                    ref={logoInputRef}
                    type="file"
                    accept="image/*"
                    className="hidden"
                    onChange={(e) => handleImageChange(e, "logo")}
                  />
                  <Button
                    type="button"
                    variant="outline"
                    size="sm"
                    onClick={() => logoInputRef.current?.click()}
                  >
                    <IoCamera className="w-4 h-4 mr-2" />
                    Change Logo
                  </Button>
                  <p className="text-xs text-muted-foreground mt-1">
                    PNG, JPG up to 5MB
                  </p>
                </div>
              </div>
            </div>

            {/* Background Upload */}
            <div>
              <Label className="text-sm font-medium mb-2 block">Background Image</Label>
              <div className="flex items-start gap-4">
                <div className="relative w-48 h-24 rounded-lg overflow-hidden border-2 border-gray-200 bg-gray-100">
                  {backgroundPreview || isValidImageUrl(company.bg_profile_url) ? (
                    <Image
                      src={backgroundPreview || company.bg_profile_url!}
                      alt="Background"
                      fill
                      className="object-cover"
                      onError={(e) => {
                        e.currentTarget.style.display = 'none';
                      }}
                    />
                  ) : (
                    <div className="w-full h-full flex items-center justify-center">
                      <IoCamera className="w-8 h-8 text-gray-400" />
                    </div>
                  )}
                </div>
                <div>
                  <input
                    ref={backgroundInputRef}
                    type="file"
                    accept="image/*"
                    className="hidden"
                    onChange={(e) => handleImageChange(e, "background")}
                  />
                  <Button
                    type="button"
                    variant="outline"
                    size="sm"
                    onClick={() => backgroundInputRef.current?.click()}
                  >
                    <IoCamera className="w-4 h-4 mr-2" />
                    Change Background
                  </Button>
                  <p className="text-xs text-muted-foreground mt-1">
                    PNG, JPG up to 5MB. Recommended: 1200x400px
                  </p>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* Verification Status */}
        <div className="flex items-center gap-3 p-4 bg-gray-50 rounded-lg border border-gray-200">
          <IoShieldCheckmarkOutline className="w-6 h-6 text-gray-600" />
          <div className="flex-1">
            <p className="text-sm font-medium text-gray-700">Verification Status</p>
            <span className={`inline-block mt-1 px-3 py-1 rounded-full text-sm font-semibold border ${getStatusColor(company.registration_status)}`}>
              {getStatusText(company.registration_status)}
            </span>
          </div>
        </div>

        {/* Company Details Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {/* Company Name */}
          <div className="space-y-2">
            <Label className="flex items-center gap-2 text-sm font-medium text-gray-700">
              <IoBusinessOutline className="w-4 h-4" />
              <span>Company Name</span>
            </Label>
            {isEditing ? (
              <Input
                value={formData.name}
                onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                placeholder="Enter company name"
                className="pl-6"
              />
            ) : (
              <p className="text-base text-gray-900 pl-6">{company.name}</p>
            )}
          </div>

          {/* Email (Read-only) */}
          <div className="space-y-2">
            <Label className="flex items-center gap-2 text-sm font-medium text-gray-700">
              <IoMailOutline className="w-4 h-4" />
              <span>Email</span>
            </Label>
            <p className="text-base text-gray-900 pl-6">{company.email}</p>
          </div>

          {/* Phone */}
          <div className="space-y-2">
            <Label className="flex items-center gap-2 text-sm font-medium text-gray-700">
              <IoCallOutline className="w-4 h-4" />
              <span>Phone</span>
            </Label>
            {isEditing ? (
              <Input
                value={formData.phone}
                onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
                placeholder="Enter phone number"
                className="pl-6"
              />
            ) : (
              <p className="text-base text-gray-900 pl-6">{company.phone}</p>
            )}
          </div>

          {/* Address */}
          <div className="space-y-2">
            <Label className="flex items-center gap-2 text-sm font-medium text-gray-700">
              <IoLocationOutline className="w-4 h-4" />
              <span>Address</span>
            </Label>
            {isEditing ? (
              <Input
                value={formData.address}
                onChange={(e) => setFormData({ ...formData, address: e.target.value })}
                placeholder="Enter address"
                className="pl-6"
              />
            ) : (
              <p className="text-base text-gray-900 pl-6">{company.address.join(", ")}</p>
            )}
          </div>

          {/* Website */}
          <div className="space-y-2 md:col-span-2">
            <Label className="flex items-center gap-2 text-sm font-medium text-gray-700">
              <IoGlobeOutline className="w-4 h-4" />
              <span>Website (Optional)</span>
            </Label>
            {isEditing ? (
              <Input
                value={formData.website}
                onChange={(e) => setFormData({ ...formData, website: e.target.value })}
                placeholder="https://example.com"
                className="pl-6"
              />
            ) : (
              <p className="text-base text-gray-900 pl-6">
                {company.department[0] || "Not provided"}
              </p>
            )}
          </div>
        </div>

        {/* Description */}
        <div className="space-y-2 pt-4 border-t">
          <Label className="flex items-center gap-2 text-sm font-medium text-gray-700">
            <IoGlobeOutline className="w-4 h-4" />
            <span>Company Description</span>
          </Label>
          {isEditing ? (
            <Textarea
              value={formData.description}
              onChange={(e) => setFormData({ ...formData, description: e.target.value })}
              placeholder="Describe your company..."
              className="pl-6 min-h-[120px]"
              rows={5}
            />
          ) : (
            <p className="text-base text-gray-900 pl-6 whitespace-pre-wrap">{company.description}</p>
          )}
        </div>

        {/* Status-specific messages */}
        {!isEditing && company.registration_status === "PENDING" && (
          <div className="mt-6 p-4 bg-blue-50 border-l-4 border-blue-500 rounded">
            <p className="text-sm font-semibold text-blue-900">Verification In Progress</p>
            <p className="text-sm text-blue-800 mt-1">
              Your company registration is currently under review by our admin team. You will receive a notification once the verification is complete.
            </p>
          </div>
        )}

        {!isEditing && company.registration_status === "REJECTED" && (
          <div className="mt-6 p-4 bg-red-50 border-l-4 border-red-500 rounded">
            <p className="text-sm font-semibold text-red-900">Verification Rejected</p>
            <p className="text-sm text-red-800 mt-1">
              Your company verification was not approved. Please upload new evidence documents in the Documents tab to re-apply for verification.
            </p>
          </div>
        )}

        {!isEditing && company.registration_status === "APPROVED" && (
          <div className="mt-6 p-4 bg-green-50 border-l-4 border-green-500 rounded">
            <p className="text-sm font-semibold text-green-900">Company Verified</p>
            <p className="text-sm text-green-800 mt-1">
              Your company has been successfully verified. You can now post jobs and manage applications.
            </p>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

"use client";

import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuTrigger,
  DropdownMenuRadioItem,
  DropdownMenuRadioGroup,
} from "@/components/ui/dropdown-menu"
import { useEffect, useState } from "react";
import { IoMdSearch } from "react-icons/io";
import { FiChevronDown } from "react-icons/fi";
import { IoMdCheckmark } from "react-icons/io";
import { Button } from "@/components/ui/button";


interface ApplicationSearchBarProps {
  applications: any[];
  setFilteredApplications: (apps: any[]) => void;
}

const ApplicationSearchBar = ({ applications, setFilteredApplications }: ApplicationSearchBarProps) => {
  const [query, setQuery] = useState("");
  const [selectedStatus, setSelectedStatus] = useState<string>("all");
  const status: string[] = ["all", "pending", "reviewed", "interview", "offered", "rejected"];

  useEffect(() => {
    try {
      const q = String(query || "").trim().toLowerCase();

      const filtered = applications.filter((a) => {
        const appStatus = String(a?.status || "").toLowerCase();
        const statusMatch = selectedStatus === "all" || appStatus === selectedStatus;

        if (!q) return statusMatch;

        const jobName = String(a?.job?.jobName || "").toLowerCase();
        const companyName = String(a?.job?.company?.name || "").toLowerCase();

        const queryMatch = jobName.includes(q) || companyName.includes(q);

        return statusMatch && queryMatch;
      });

      setFilteredApplications(filtered);
    } catch (err) {
      console.error("Error filtering applications:", err);
    }
  }, [applications, query, selectedStatus, setFilteredApplications]);

  return (
    <div className="mx-auto">
      <div className="flex flex-col gap-2">
        <div className="flex items-center gap-6 border border-gray-100 rounded-lg px-7 py-4 mb-6 w-full shadow-md relative">
          <div className="absolute top-0 left-0 bottom-0 w-1.5 bg-[#34BFA3] rounded-l-md" />
          <div className="pl-4 w-full">
            <div className="flex items-center gap-4 w-full">
              <div className="relative flex-1">
                <IoMdSearch className="absolute left-3 top-1/2 -translate-y-1/2 text-gray-500" />
                <input
                  value={query}
                  onChange={(e) => setQuery(e.target.value)}
                  placeholder="Search jobs or companies"
                  className="pl-10 pr-3 py-2 bg-white rounded-md border-gray-100 shadow-sm w-full h-10"
                />
              </div>
              <div className="flex-shrink-0 flex items-center gap-3">
                <div className="hidden sm:block">
                 <div className="md:w-[180px] w-full flex justify-end">
                    <DropdownMenu>
                        <DropdownMenuTrigger asChild>
                        <Button className="group bg-white border border-gray-200 md:w-[180px] text-gray-800 font-semibold rounded-full px-4 flex items-center justify-between gap-2 transition-colors hover:bg-[#34BFA3] hover:text-white focus:outline-none focus:ring-0">
                            <span className="flex items-center gap-2">
                              <span className="hidden sm:inline">{selectedStatus === 'all' ? 'All Statuses' : selectedStatus.charAt(0).toUpperCase() + selectedStatus.slice(1)}</span>
                            </span>
                            <FiChevronDown className="w-4 h-4 text-gray-600 group-hover:text-white" />
                        </Button>
                        </DropdownMenuTrigger>

                        <DropdownMenuContent className="w-56 p-2">
                        <div className="px-2 py-1 text-xs text-gray-500">Filter by status</div>
                        <DropdownMenuRadioGroup value={selectedStatus} onValueChange={(value) => {setSelectedStatus(value)}}>
                          {status.map((s) => (
                            <DropdownMenuRadioItem
                              key={s}
                              value={s}
                              className={`flex items-center justify-between pl-8 pr-3 py-2 rounded-md text-sm ${
                                selectedStatus === s ? 'bg-gray-100 text-gray-900' : 'hover:bg-gray-50'
                              }`}
                            >
                              <span className="capitalize">{s === 'all' ? 'All' : s}</span>
                              {selectedStatus === s && <IoMdCheckmark className="w-4 h-4 text-green-600" />}
                            </DropdownMenuRadioItem>
                          ))}
                        </DropdownMenuRadioGroup>
                        </DropdownMenuContent>
                    </DropdownMenu>
                    </div>
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
    );
}
export default ApplicationSearchBar;

"use client";

import { useState, useRef } from "react";
import { Student } from "@/types/user";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { toast } from "sonner";
import { IoPersonOutline, IoIdCardOutline, IoMailOutline, IoCallOutline, IoSchoolOutline, IoShieldCheckmarkOutline, IoSave, IoClose, IoCamera, IoPersonCircleOutline } from "react-icons/io5";
import Image from "next/image";
import { isValidImageUrl } from "@/lib/validateImageUrl";
import { useSession } from "next-auth/react";
import Link from "next/link";

interface ProfileTabProps {
  student: Student;
  onUpdate: () => void;
}

export default function ProfileTab({ student, onUpdate }: ProfileTabProps) {
  const [isEditing, setIsEditing] = useState(false);
  const [isSaving, setIsSaving] = useState(false);
  const [formData, setFormData] = useState({
    firstname: student.firstname,
    lastname: student.lastname,
    faculty: student.faculty,
    year: student.year,
    phone: student.phone,
  });

  // Image upload refs and previews
  const logoInputRef = useRef<HTMLInputElement>(null);
  const [logoPreview, setLogoPreview] = useState<string | null>(null);
  const [logoFile, setLogoFile] = useState<File | null>(null);
  const { data: session, update: updateSession } = useSession();

  const handleChange = (field: string, value: string | number) => {
    setFormData(prev => ({ ...prev, [field]: value }));
  };

  const handleImageChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      // Validate file type
      if (!file.type.startsWith("image/")) {
        toast.error("Please select an image file");
        return;
      }

      // Validate file size (max 5MB)
      if (file.size > 5 * 1024 * 1024) {
        toast.error("Image size must be less than 5MB");
        return;
      }

      const reader = new FileReader();
      reader.onloadend = () => {
        setLogoPreview(reader.result as string);
        setLogoFile(file);
      };
      reader.readAsDataURL(file);
    }
  };

  const getStatusColor = (status: string, emailVerified: boolean) => {
    // For alumni who are approved but haven't verified email, show blue (pending email verification)
    if (status === "APPROVED" && student.student_status === "ALUMNI" && !emailVerified) {
      return "bg-blue-100 text-blue-800 border-blue-300";
    }

    switch (status) {
      case "APPROVED":
        return "bg-green-100 text-green-800 border-green-300";
      case "PENDING":
        return "bg-yellow-100 text-yellow-800 border-yellow-300";
      case "REJECTED":
        return "bg-red-100 text-red-800 border-red-300";
      default:
        return "bg-gray-100 text-gray-800 border-gray-300";
    }
  };

  const getStatusText = (status: string, emailVerified: boolean) => {
    // For alumni who are approved but haven't verified email
    if (status === "APPROVED" && student.student_status === "ALUMNI" && !emailVerified) {
      return "Email Verification Required";
    }

    switch (status) {
      case "APPROVED":
        return "Verified";
      case "PENDING":
        return "Verification Pending";
      case "REJECTED":
        return "Verification Rejected";
      default:
        return status;
    }
  };

  const handleSave = async () => {
    // Validation
    if (formData.firstname.trim().length < 2) {
      toast.error("First name must be at least 2 characters");
      return;
    }
    if (formData.lastname.trim().length < 2) {
      toast.error("Last name must be at least 2 characters");
      return;
    }
    if (formData.phone && !/^\d{10,}$/.test(formData.phone)) {
      toast.error("Phone number must be at least 10 digits");
      return;
    }

    setIsSaving(true);

    try {
      // If there's a profile image, upload it separately first
      if (logoFile) {
        const imageFormData = new FormData();
        imageFormData.append("file", logoFile);

        const imageRes = await fetch("/api/students/profile-image", {
          method: "POST",
          body: imageFormData,
        });

        if (!imageRes.ok) {
          const error = await imageRes.json();
          toast.error(error.error || "Failed to upload profile image");
          setIsSaving(false);
          return;
        }

        const imageData = await imageRes.json();

        // Update session with new logoUrl
        if (imageData.profile_url) {
          await updateSession({
            user: {
              ...session?.user,
              logoUrl: imageData.profile_url,
            },
          });
        }
      }

      // Update other profile fields
      const res = await fetch("/api/students/profile", {
        method: "PUT",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          name: `${formData.firstname} ${formData.lastname}`,
          faculty: formData.faculty,
          year: formData.year,
          phone: formData.phone,
        }),
      });

      if (!res.ok) {
        const errorData = await res.json();
        console.error("❌ Update failed:", errorData);
        toast.error(errorData.error || "Failed to update profile");
        return;
      }

      toast.success("Profile updated successfully");
      setIsEditing(false);
      setLogoPreview(null);
      setLogoFile(null);
      onUpdate();
    } catch (error) {
      console.error("Error updating profile:", error);
      toast.error("Error updating profile");
    } finally {
      setIsSaving(false);
    }
  };

  const handleCancel = () => {
    setFormData({
      firstname: student.firstname,
      lastname: student.lastname,
      faculty: student.faculty,
      year: student.year,
      phone: student.phone,
    });
    setLogoPreview(null);
    setLogoFile(null);
    setIsEditing(false);
  };

  return (
    <Card>
      <CardHeader>
        <div className="flex items-center justify-between">
          <div>
            <CardTitle>Student Information</CardTitle>
            <CardDescription>
              {isEditing ? "Edit your student profile details" : "View your student profile details"}
            </CardDescription>
          </div>
          <div className="flex gap-2">
            {!isEditing ? (
              <Button onClick={() => setIsEditing(true)} data-testid="edit-profile-btn">
                Edit Profile
              </Button>
            ) : (
              <>
                <Button variant="outline" onClick={handleCancel} disabled={isSaving} data-testid="cancel-profile-btn">
                  <IoClose className="w-4 h-4 mr-2" />
                  Cancel
                </Button>
                <Button onClick={handleSave} disabled={isSaving} data-testid="save-profile-btn">
                  <IoSave className="w-4 h-4 mr-2" />
                  {isSaving ? "Saving..." : "Save Changes"}
                </Button>
              </>
            )}
          </div>
        </div>
      </CardHeader>
      <CardContent className="space-y-6">
        {/* Profile Image Section */}
        {isEditing && (
          <div className="space-y-4 pb-6 border-b">
            <h3 className="text-sm font-medium">Profile Image</h3>

            {/* Profile Image Upload */}
            <div>
              <Label className="text-sm font-medium mb-2 block">Profile Picture</Label>
              <div className="flex items-center gap-4">
                <div className="relative w-24 h-24 rounded-full overflow-hidden border-2 border-gray-200 bg-gray-100">
                  {logoPreview || isValidImageUrl(student.profile_url) ? (
                    <Image
                      src={logoPreview || student.profile_url!}
                      alt="Profile Picture"
                      fill
                      className="object-cover"
                      onError={(e) => {
                        e.currentTarget.style.display = 'none';
                      }}
                    />
                  ) : (
                    <div className="w-full h-full flex items-center justify-center">
                      <IoPersonCircleOutline className="w-12 h-12 text-gray-400" />
                    </div>
                  )}
                </div>
                <div>
                  <input
                    ref={logoInputRef}
                    type="file"
                    accept="image/*"
                    data-testid="profile-picture-input"
                    className="hidden"
                    onChange={handleImageChange}
                  />
                  <Button
                    type="button"
                    variant="outline"
                    size="sm"
                    data-testid="change-picture-btn"
                    onClick={() => logoInputRef.current?.click()}
                  >
                    <IoCamera className="w-4 h-4 mr-2" />
                    Change Picture
                  </Button>
                  <p className="text-xs text-muted-foreground mt-1">
                    PNG, JPG up to 5MB
                  </p>
                </div>
              </div>
            </div>
          </div>
        )}

        {/* Verification Status */}
        <div className="flex items-center gap-3 p-4 bg-gray-50 rounded-lg border border-gray-200">
          <IoShieldCheckmarkOutline className="w-6 h-6 text-gray-600" />
          <div className="flex-1">
            <p className="text-sm font-medium text-gray-700">Verification Status</p>
            <span className={`inline-block mt-1 px-3 py-1 rounded-full text-sm font-semibold border ${getStatusColor(student.verification_status, student.email_verified)}`}>
              {getStatusText(student.verification_status, student.email_verified)}
            </span>
          </div>
        </div>

        {/* Student Details Grid */}
        <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
          {/* Student ID (Read-only) */}
          <div className="space-y-2">
            <Label className="flex items-center gap-2 text-sm font-medium text-gray-700">
              <IoIdCardOutline className="w-4 h-4" />
              <span>Student ID</span>
            </Label>
            <p className="text-base text-gray-900 pl-6">{student.student_id}</p>
          </div>

          {/* Email (Read-only) */}
          <div className="space-y-2">
            <Label className="flex items-center gap-2 text-sm font-medium text-gray-700">
              <IoMailOutline className="w-4 h-4" />
              <span>Email</span>
            </Label>
            <p className="text-base text-gray-900 pl-6">{student.email}</p>
          </div>

          {/* First Name */}
          <div className="space-y-2">
            <Label className="flex items-center gap-2 text-sm font-medium text-gray-700">
              <IoPersonOutline className="w-4 h-4" />
              <span>First Name</span>
            </Label>
            {isEditing ? (
              <Input
                value={formData.firstname}
                onChange={(e) => handleChange("firstname", e.target.value)}
                data-testid="input-firstname"
                placeholder="Enter first name"
                className="pl-6"
              />
            ) : (
              <p className="text-base text-gray-900 pl-6">{student.firstname}</p>
            )}
          </div>

          {/* Last Name */}
          <div className="space-y-2">
            <Label className="flex items-center gap-2 text-sm font-medium text-gray-700">
              <IoPersonOutline className="w-4 h-4" />
              <span>Last Name</span>
            </Label>
            {isEditing ? (
              <Input
                value={formData.lastname}
                onChange={(e) => handleChange("lastname", e.target.value)}
                data-testid="input-lastname"
                placeholder="Enter last name"
                className="pl-6"
              />
            ) : (
              <p className="text-base text-gray-900 pl-6">{student.lastname}</p>
            )}
          </div>

          {/* Faculty */}
          <div className="space-y-2">
            <Label className="flex items-center gap-2 text-sm font-medium text-gray-700">
              <IoSchoolOutline className="w-4 h-4" />
              <span>Faculty</span>
            </Label>
            {isEditing ? (
              <Select
                value={formData.faculty}
                onValueChange={(value) => handleChange("faculty", value)}
              >
                <SelectTrigger className="pl-6" data-testid="select-faculty">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="Software and Knowledge Engineering (SKE)" data-testid="ske">
                    Software and Knowledge Engineering (SKE)
                  </SelectItem>
                  <SelectItem value="Computer Engineering (CPE)" data-testid="cpe">
                    Computer Engineering (CPE)
                  </SelectItem>
                </SelectContent>
              </Select>
            ) : (
              <p className="text-base text-gray-900 pl-6">{student.faculty}</p>
            )}
          </div>

          {/* Year */}
          <div className="space-y-2">
            <Label className="flex items-center gap-2 text-sm font-medium text-gray-700">
              <IoSchoolOutline className="w-4 h-4" />
              <span>Year</span>
            </Label>
            {isEditing ? (
              <Select
                value={String(formData.year)}
                onValueChange={(value) => handleChange("year", value === "Alumni" ? value : parseInt(value))}
              >
                <SelectTrigger className="pl-6" data-testid="select-year">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {[1, 2, 3, 4, 5, 6, 7, 8].map((year) => (
                    <SelectItem key={year} value={String(year)} data-testid={`year-${year}`}>
                      Year {year}
                    </SelectItem>
                  ))}
                  <SelectItem value="Alumni" data-testid="year-alumni">Alumni</SelectItem>
                </SelectContent>
              </Select>
            ) : (
              <p className="text-base text-gray-900 pl-6">
                {student.year === "Alumni" ? "Alumni" : `Year ${student.year}`}
              </p>
            )}
          </div>

          {/* Phone */}
          <div className="space-y-2">
            <Label className="flex items-center gap-2 text-sm font-medium text-gray-700">
              <IoCallOutline className="w-4 h-4" />
              <span>Phone</span>
            </Label>
            {isEditing ? (
              <Input
                value={formData.phone}
                onChange={(e) => handleChange("phone", e.target.value)}
                data-testid="input-phone"
                placeholder="Enter phone number"
                className="pl-6"
              />
            ) : (
              <p className="text-base text-gray-900 pl-6">{student.phone}</p>
            )}
          </div>
        </div>

        {/* Status-specific messages */}
        {!isEditing && student.verification_status === "PENDING" && (
          <div className="mt-6 p-4 bg-blue-50 border-l-4 border-blue-500 rounded">
            <p className="text-sm font-semibold text-blue-900">Verification In Progress</p>
            <p className="text-sm text-blue-800 mt-1">
              Your student registration is currently under review by our admin team. You will receive a notification once the verification is complete.
            </p>
          </div>
        )}

        {!isEditing && student.verification_status === "REJECTED" && (
          <div className="mt-6 p-4 bg-red-50 border-l-4 border-red-500 rounded">
            <p className="text-sm font-semibold text-red-900">Verification Rejected</p>
            <p className="text-sm text-red-800 mt-1">
              Your student verification was not approved. Please upload new documents in the Documents tab to re-apply for verification.
            </p>
          </div>
        )}

        {!isEditing && student.verification_status === "APPROVED" && student.student_status === "ALUMNI" && !student.email_verified && (
          <div className="mt-6 p-4 bg-blue-50 border-l-4 border-blue-500 rounded">
            <div className="flex items-center justify-between">
              <div className="flex-1">
                <p className="text-sm font-semibold text-blue-900">Admin Approval Complete - Email Verification Required</p>
                <p className="text-sm text-blue-800 mt-1">
                  Your alumni status has been approved by an admin! Please verify your KU email to complete registration and start applying for jobs.
                </p>
              </div>
              <Link href={`/student/verify-email?email=${encodeURIComponent(student.email)}`}>
                <Button className="ml-4 bg-blue-600 hover:bg-blue-700">
                  Verify Email
                </Button>
              </Link>
            </div>
          </div>
        )}

        {!isEditing && student.verification_status === "APPROVED" && student.email_verified && (
          <div className="mt-6 p-4 bg-green-50 border-l-4 border-green-500 rounded">
            <p className="text-sm font-semibold text-green-900">Student Verified</p>
            <p className="text-sm text-green-800 mt-1">
              Your student account has been successfully verified. You can now apply for jobs and manage your applications.
            </p>
          </div>
        )}
      </CardContent>
    </Card>
  );
}

"use client";

import { Button } from "@/components/ui/button";
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from "@/components/ui/card";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Alert, AlertDescription } from "@/components/ui/alert";
import { useRouter, useSearchParams } from "next/navigation";
import { useState, useEffect } from "react";
import { Mail, CheckCircle, XCircle, Loader2 } from "lucide-react";
import { useSession } from "next-auth/react";

export default function VerifyEmailPage() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const { data: session, update } = useSession();
  const email = searchParams.get("email");
  const name = searchParams.get("name");

  const [code, setCode] = useState("");
  const [isLoading, setIsLoading] = useState(false);
  const [isSendingCode, setIsSendingCode] = useState(false);
  const [error, setError] = useState("");
  const [success, setSuccess] = useState(false);
  const [resendCountdown, setResendCountdown] = useState(0);
  const [hasSentInitialCode, setHasSentInitialCode] = useState(false);

  // Auto-send verification email on page load (only once)
  useEffect(() => {
    if (email && !success && !hasSentInitialCode) {
      setHasSentInitialCode(true);
      sendVerificationCode();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Countdown timer for resend button
  useEffect(() => {
    if (resendCountdown > 0) {
      const timer = setTimeout(() => {
        setResendCountdown(resendCountdown - 1);
      }, 1000);
      return () => clearTimeout(timer);
    }
  }, [resendCountdown]);

  const sendVerificationCode = async () => {
    if (!email) {
      setError("Email address is missing. Please register again.");
      return;
    }

    setIsSendingCode(true);
    setError("");

    try {
      const response = await fetch("/api/students/send-verification", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email, studentName: name }),
      });

      const data = await response.json();

      if (!response.ok) {
        setError(data.message || data.error || "Failed to send verification code");
      } else {
        setResendCountdown(60); // Start 60-second countdown
      }
    } catch (err) {
      setError("Failed to send verification code. Please try again.");
      console.error("Error sending verification code:", err);
    } finally {
      setIsSendingCode(false);
    }
  };

  const handleVerify = async (e: React.FormEvent) => {
    e.preventDefault();

    if (!code || code.length !== 6) {
      setError("Please enter a 6-digit verification code");
      return;
    }

    setIsLoading(true);
    setError("");

    try {
      const response = await fetch("/api/students/verify-email", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email, token: code }),
      });

      const data = await response.json();

      if (!response.ok) {
        setError(data.message || data.error || "Verification failed");
      } else {
        setSuccess(true);

        // Update the session to reflect the new verification status
        await update({
          ...session,
          user: {
            ...session?.user,
            emailVerified: true,
            verificationStatus: "APPROVED"
          }
        });

        // Use window.location.href for hard redirect to ensure session is fully propagated
        setTimeout(() => {
          window.location.href = "/student/dashboard";
        }, 2000);
      }
    } catch (err) {
      setError("An error occurred. Please try again.");
      console.error("Error verifying email:", err);
    } finally {
      setIsLoading(false);
    }
  };

  const handleCodeChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    const value = e.target.value.replace(/\D/g, "").slice(0, 6);
    setCode(value);
  };

  if (!email) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50 p-4">
        <Card className="w-full max-w-md">
          <CardHeader className="text-center">
            <XCircle className="w-16 h-16 text-red-500 mx-auto mb-4" />
            <CardTitle>Invalid Access</CardTitle>
            <CardDescription>
              No email address provided. Please register first.
            </CardDescription>
          </CardHeader>
          <CardContent>
            <Button
              onClick={() => router.push("/register/student")}
              className="w-full"
            >
              Go to Registration
            </Button>
          </CardContent>
        </Card>
      </div>
    );
  }

  if (success) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-gray-50 p-4">
        <Card className="w-full max-w-md">
          <CardHeader className="text-center">
            <CheckCircle className="w-16 h-16 text-green-500 mx-auto mb-4" />
            <CardTitle>Email Verified!</CardTitle>
            <CardDescription>
              Your KU email has been successfully verified. Redirecting to your dashboard...
            </CardDescription>
          </CardHeader>
        </Card>
      </div>
    );
  }

  return (
    <div className="min-h-screen flex items-center justify-center bg-gray-50 p-4">
      <Card className="w-full max-w-md">
        <CardHeader className="text-center">
          <div className="w-16 h-16 bg-blue-100 rounded-full flex items-center justify-center mx-auto mb-4">
            <Mail className="w-8 h-8 text-blue-700" />
          </div>
          <CardTitle className="text-2xl">Verify Your Email</CardTitle>
          <CardDescription>
            We&apos;ve sent a 6-digit code to
            <br />
            <strong className="text-gray-900">{email}</strong>
          </CardDescription>
        </CardHeader>

        <CardContent>
          {error && (
            <Alert variant="destructive" className="mb-4">
              <AlertDescription>{error}</AlertDescription>
            </Alert>
          )}

          <form onSubmit={handleVerify} className="space-y-4">
            <div>
              <Label htmlFor="code">Verification Code</Label>
              <Input
                id="code"
                type="text"
                inputMode="numeric"
                pattern="[0-9]*"
                maxLength={6}
                value={code}
                onChange={handleCodeChange}
                placeholder="000000"
                className="mt-1 text-center text-2xl tracking-widest font-mono"
                disabled={isLoading}
              />
              <p className="text-xs text-gray-500 mt-2 text-center">
                Enter the 6-digit code sent to your email
              </p>
            </div>

            <Button
              type="submit"
              className="w-full"
              disabled={isLoading || code.length !== 6}
            >
              {isLoading ? (
                <>
                  <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                  Verifying...
                </>
              ) : (
                "Verify Email"
              )}
            </Button>

            <div className="text-center">
              <p className="text-sm text-gray-600">
                Didn&apos;t receive the code?
              </p>
              <Button
                type="button"
                variant="link"
                onClick={sendVerificationCode}
                disabled={isSendingCode || resendCountdown > 0}
                className="text-blue-600"
              >
                {isSendingCode ? (
                  <>
                    <Loader2 className="w-4 h-4 mr-2 animate-spin" />
                    Sending...
                  </>
                ) : resendCountdown > 0 ? (
                  `Resend code in ${resendCountdown}s`
                ) : (
                  "Resend Code"
                )}
              </Button>
            </div>
          </form>

          <div className="mt-6 p-4 bg-amber-50 border border-amber-200 rounded-md">
            <p className="text-xs text-amber-800">
              <strong>⏰ Important:</strong> The verification code expires in 15 minutes.
            </p>
          </div>
        </CardContent>
      </Card>
    </div>
  );
}

"use client";

import { FiEdit } from "react-icons/fi";
import { Button } from "./ui/button";
import { Input } from "./ui/input";
import { JobPostFormData, JobInfo } from "@/types/job";
import { useEffect, useState, useMemo } from "react";
import JobDescriptionCard from "./JobDescriptionCard";
import SkillCombobox from "./SkillCombobox";
import LocationCombobox from "./LocationCombobox";
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogTrigger } from "@/components/ui/dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select"

interface EditJobCardProps {
  job: JobInfo;
  formData: JobPostFormData;
  setFormData: (data: JobPostFormData) => void;
  handleEdit?: () => Promise<boolean> | boolean;
  categories: string[];
  jobTypes: string[];
  arrangements: string[];
  tags: string[];
}

interface CompanyProps {
  name: string;
  profile_url: string;
  bg_profile_url: string;
}

export default function EditJobCard({ job,formData, setFormData, handleEdit, 
  categories, jobTypes, arrangements,tags}: EditJobCardProps) {
  const [open, setOpen] = useState(false);
  const [categoryList, setCategoryList] = useState<string[]>([]);
  const [jobTypeList, setJobTypeList] = useState<string[]>([]);
  const [jobArrangementList, setJobArrangementList] = useState<string[]>([]);
  const [preview, setPreview] = useState<boolean>(false);
  const [company, setCompany] = useState<CompanyProps | null>(null);
  const [skillOptions, setSkillOptions] = useState<string[]>([]);
  const ALLOWED_DOCS = ["Resume", "CV", "Portfolio", "Transcript"];

  useEffect(() => {
    setCategoryList(categories);
    setJobTypeList(jobTypes);
    setJobArrangementList(arrangements);
